// and master-page references (left/right masters become single-page masters).
//
// Usage: Open your document, then run this script.
//
// Notes:
// - Creates a new single-page document and duplicates pages over.
// - Rebuilds masters as single-page masters (Left/Right) and reapplies them.
// - Preserves layers order, margins, page size overrides, items positions, styles, etc.

(function () {
    if (app.documents.length === 0) {
        alert("Open a document before running this script.");
        return;
    }

    var src = app.activeDocument;
    var undoName = "Convert spreads to single-page document";
    app.doScript(function () { main(src); }, ScriptLanguage.JAVASCRIPT, undefined, UndoModes.ENTIRE_SCRIPT, undoName);

