        // Performance guards
        var oldRedraw = app.scriptPreferences.enableRedraw;
        var oldPreflight = app.preflightOptions.preflightOff;
        var oldInteraction = app.scriptPreferences.userInteractionLevel;
        app.scriptPreferences.enableRedraw = false;
        app.preflightOptions.preflightOff = true;
        app.scriptPreferences.userInteractionLevel = UserInteractionLevels.NEVER_INTERACT;

        try {
            // Create target doc with single pages, clone key prefs from source
            var tgt = app.documents.add();
            cloneDocumentPreferences(src, tgt);

            // Ensure target has single pages
            tgt.documentPreferences.facingPages = false;
            tgt.allowDocumentPagesShuffle = false;

            // Rebuild layers in same stacking order as source
            copyLayersStructure(src, tgt);

            // Build single-page masters in target and create a mapping
            // Map key: srcMasterSpread.id + "|" + side ("L","R","S") -> target MasterSpread
            var masterMap = buildSinglePageMasters(src, tgt);

            // Duplicate all pages from source to target, in order, reapplying mapped masters
            duplicatePagesWithMasterRemap(src, tgt, masterMap);

            // Optional: Save or bring target to front
            tgt.viewPreferences.rulerOrigin = src.viewPreferences.rulerOrigin;
            tgt.viewPreferences.horizontalMeasurementUnits = src.viewPreferences.horizontalMeasurementUnits;
            tgt.viewPreferences.verticalMeasurementUnits = src.viewPreferences.verticalMeasurementUnits;

            app.activeWindow.activePage = tgt.pages[0];

        } catch (e) {
            alert("Error: " + e + "\nLine: " + (e.line || "?"));
            throw e;
        } finally {
            // Restore performance settings
            app.scriptPreferences.enableRedraw = oldRedraw;
            app.preflightOptions.preflightOff = oldPreflight;
            app.scriptPreferences.userInteractionLevel = oldInteraction;
        }
    }

