        // Basic document setup mirrored from source
        var sp = src.documentPreferences;
        var tp = tgt.documentPreferences;

        tp.pageWidth = sp.pageWidth;
        tp.pageHeight = sp.pageHeight;
        tp.pageOrientation = sp.pageOrientation;
        tp.intent = sp.intent;
        tp.pageCount = 1;
        tp.facingPages = false;

        // Bleed/slug
