        tgt.documentPreferences.documentBleedBottomOffset = sp.documentBleedBottomOffset;
        tgt.documentPreferences.documentBleedInsideOrLeftOffset = sp.documentBleedInsideOrLeftOffset;
        tgt.documentPreferences.documentBleedOutsideOrRightOffset = sp.documentBleedOutsideOrRightOffset;
        tgt.documentPreferences.slugTopOffset = sp.slugTopOffset;
        tgt.documentPreferences.slugBottomOffset = sp.slugBottomOffset;
        tgt.documentPreferences.slugInsideOrLeftOffset = sp.slugInsideOrLeftOffset;
        tgt.documentPreferences.slugRightOrOutsideOffset = sp.slugRightOrOutsideOffset;

        // Ruler/units
        tgt.viewPreferences.rulerOrigin = src.viewPreferences.rulerOrigin;
        tgt.viewPreferences.horizontalMeasurementUnits = src.viewPreferences.horizontalMeasurementUnits;
        tgt.viewPreferences.verticalMeasurementUnits = src.viewPreferences.verticalMeasurementUnits;

        // Grids/guides preferences are mostly per doc; copy key ones if needed
        tgt.gridPreferences.documentGridShown = src.gridPreferences.documentGridShown;
        tgt.guidesPreferences.guidesShown = src.guidesPreferences.guidesShown;
    }

    function copyLayersStructure(src, tgt) {
