            tgt.layers[0].name = src.layers[0].name;
            tgt.layers[0].visible = src.layers[0].visible;
            tgt.layers[0].locked = false;
            tgt.layers[0].printable = src.layers[0].printable;
        }

        for (var i = 0; i < srcLayers.length; i++) {
