                var tmsL = tgt.masterSpreads.add();
                tmsL.name = leftName;
                copyMasterPageContent(ms.pages[0], tmsL.pages[0]);
                map[ms.id + "|L"] = tmsL;

                var tmsR = tgt.masterSpreads.add();
                tmsR.name = rightName;
                copyMasterPageContent(ms.pages[1], tmsR.pages[0]);
                map[ms.id + "|R"] = tmsR;
            }
        }
        return map;
    }

    function uniqueMasterName(doc, base, registry) {
        var name = base;
        var n = 1;
        while (registry[name] || (doc.masterSpreads.itemByName(name) && doc.masterSpreads.itemByName(name).isValid)) {
