        tgtMP.bottom = srcMP.bottom;
        tgtMP.left = srcMP.left;
        tgtMP.right = srcMP.right;
        tgtMP.columnCount = srcMP.columnCount;
        tgtMP.columnGutter = srcMP.columnGutter;
    }

