        // Prepare: we will append pages. Ensure target has exactly one page to start; we'll reuse it for first page to avoid an extra
        var firstPlaced = false;

        // Build page list in reading order
        var srcPages = [];
        for (var i = 0; i < src.pages.length; i++) srcPages.push(src.pages[i]);

