            var spg = srcPages[i];

            // Duplicate or move page to target
            var newPage;
            if (!firstPlaced) {
                // Place into existing page: clear it first if needed
                newPage = tgt.pages[0];
                firstPlaced = true;

                // To preserve per-page size and items positioning, duplicate spg into tgt after first page, then remove initial?
                // Safer: actually duplicate to end, then remove the initial blank first page when done.
                // So we won't reuse first page; we will always duplicate, then delete the initial stub at the end.
                // Implement by always duplicating:
                firstPlaced = false; // keep false and handle deletion later
            }

            // Duplicate page into target at end
            // Use try variants for different InDesign versions
            try {
                newPage = spg.duplicate(LocationOptions.AT_END, tgt);
            } catch (_) {
                try {
                    newPage = spg.duplicate(LocationOptions.AT_END, tgt.pages[-1]);
                } catch (e) {
                    // Fallback: duplicate into source then move
                    var temp = spg.duplicate(LocationOptions.AFTER, src.pages[-1]);
                    newPage = temp.move(LocationOptions.AT_END, tgt);
                }
