            var srcMS = spg.appliedMaster; // may be null
            var sideKey = pageSideKey(spg);
            if (srcMS && sideKey) {
                var key = srcMS.id + "|" + sideKey;
                if (!masterMap[key] && sideKey !== "S") {
                    // If original was single master but page had side, try "S"
                    key = srcMS.id + "|S";
                }
                if (masterMap[key]) {
                    newPage.appliedMaster = masterMap[key];
                } else {
                    // If no mapping exists (rare), clear master to retain items only
                    // or leave whatever came along with duplication.
                }
